    for (var i = 0; i < datas.length; i++) {
        var id_function = datas[i]._id

        if (datas[i].function_in_elements_list !== undefined) {
            for (var y = 0; y < datas[i].function_in_elements_list.length; y++) {
                //FOR KEYPAD
                if (datas[i].function_in_elements_list[y].type === "Keypad") {
                    var keypadLength = datas[i].function_in_elements_list[y].info.length;
                    msg.state = msg._id.slice(-keypadLength);
