function boucle() {
    var data = datas[func];

    if (delay > 0) {
        setTimeout(function () {
            action(data);
        }, delay);
    }
    else {
        action(data);
    }

}

function action(data) {
    delay = 0;
    actions--;
    func++;

    switch (data.type) {

        //MECANSISM
        case "Mecanism":
            if (data.info.includes("__SCREEN__")) {

                msg.screen_id = data.info.substr(10);
                msg.screen_power = data.detail;

                node.send([null, null, null, null, null, null, null, null, null, msg, null])
                break;
            }

            else {
                if (data.detail === 2) {
                    msg.tilt = data.other;
                }

                msg.func = func;
                msg.mecanism = data.detail;
                msg.meca_id = data.info;

                node.send([null, msg, null, null, null, null, null, null, null, null, null])
                break;
            }

        //DELAY
        case "Delay":
            if (data.info === "Simple") {
                delay = data.detail * 1000;
            }
            else if (data.info === "SoundEnd" || data.info === "VideoEnd") {
                var Sound = data.detail.replace(".mp3", "(mp3)").replace(".wav", "(wav)").replace(".ogg", "(ogg)");
                datas.splice(0, +func)
                var remaining_functions = {}
                remaining_functions.function_out_elements_list = datas;
                remaining_functions._id = msg._id;
                global.set('Memory.MediaDelay.' + Sound, remaining_functions)
                msg.MediaEnd = Sound;

                delete msg.payload;
                delete msg._event;
                delete msg.mecanism;
                delete msg.delai;
                delete msg.image;
                delete msg.sound;
                delete msg.video;
                delete msg.volume;
                delete msg.unique;
                delete msg.timer;
                delete msg.message;
                delete msg.meca_id;
                delete msg.active;
                delete msg.func;
                delete msg.player;
                delete msg.speakers;

                node.send([null, null, null, null, null, null, null, null, null, null, msg]);
                func = funcs;
            }
            break;

        //IMAGE
        case "Image":
            if (data.detail === 1) {
                if (data.other === "fullscreen") {
                    msg.fullScreenImage = data.info;
                }
                else {
                    msg.clueImage = data.info;
                }
            }
            else {
                msg.clueImage = "";
                msg.fullScreenImage = "";
            }

            msg.screen = data.screens || [];

            node.send([null, null, msg, null, null, null, null, null, null, null, null])
            break;

        //SOUND
        case "Sound":
            if (data.detail === 1) {
                msg.player = "Play";
            }
            else if (data.detail === 2) {
                msg.player = "Loop";
            }
            else {
                msg.player = "Stop";
            }

            msg.volume = data.other;
            msg.speakers = data.speakers;
            msg.sound = data.info;
            msg.unique = data.speakers + "-" + msg.player + "-" + data.info;

            node.send([null, null, null, msg, null, null, null, null, null, null, null]);
            break;

        //VIDEO
        case "Video":
            if (data.detail === 1) {
                msg.player = "Play";
            }
            else if (data.detail === 2) {
                msg.player = "Loop";
            }
            else {
                msg.player = "Stop";
            }

            msg.volume = data.other;
            msg.speakers = data.speakers;
            msg.screens = data.screens || [];
            msg.video = data.info;
            msg.unique = data.screens + "-" + msg.player + "-" + data.info;

            node.send([null, null, null, null, msg, null, null, null, null, null, null])
            break;

        //TIMER
        case "Timer":
            msg.action = data.info;
            msg.time = data.detail;

            node.send([null, null, null, null, null, msg, null, null, null, null, null])
            break;

        //MESSAGE
        case "Message":
            msg.message = data.detail;
            msg.delai = +data.other;
            msg.color = data.info;

            node.send([null, null, null, null, null, null, msg, null, null, null, null])
