            break;

        //FUNCTION OUT
        case "Function_Out":
            msg.payload = {};
            msg.payload.step_action = data.info;

            node.send([null, null, null, null, null, null, null, null, msg, null, null])
            break;
    }

    if (actions === 0) {
        msg.active = false;
        node.send([msg, null, null, null, null, null, null, null, null, null, null])
    }

