            msg.message = data.detail;
            msg.delai = +data.other;
            msg.color = data.info;

            node.send([null, null, null, null, null, null, msg, null, null, null, null])
            break;

        //Keypad
        case "Keypad":
            msg.keypad = data.info;

            node.send([null, null, null, null, null, null, null, msg, null, null, null])
            break;

        //FUNCTION OUT
        case "Function_Out":
            msg.payload = {};
            msg.payload.step_action = data.info;

            node.send([null, null, null, null, null, null, null, null, msg, null, null])
            break;
    }

    if (actions === 0) {
        msg.active = false;
        node.send([msg, null, null, null, null, null, null, null, null, null, null])
    }

